function splitLines(t){ return String(t||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function weekThemes(n, goals){
  n=parseInt(n,10)||16; if(n<4)n=4; if(n>24)n=24;
  var weeks=['绪论与课程导学'];
  var body=n-4;
  for(var i=0;i<body;i++){ weeks.push(goals[i%Math.max(goals.length,1)]||'专题讲授与练习'); }
  weeks.push('综合复习与答疑');
  weeks.push('期末考核');
  weeks.push('机动与补遗');
  return weeks;
}
function assessPlan(mode){
  mode=String(mode||'考试为主');
  if(mode.indexOf('项目')>=0) return [['平时表现',20],['阶段作业',30],['项目答辩',50]];
  if(mode.indexOf('考查')>=0) return [['平时表现',30],['阶段测验',30],['期末作品',40]];
  return [['平时作业',20],['期中测验',30],['期末考试',50]];
}
function buildSyllabus(o){
  o=o||{};
  var name=String(o.name||'').trim()||'（待填写课程名）';
  var weeks=parseInt(o.weeks,10)||16; if(weeks<4)weeks=4; if(weeks>24)weeks=24;
  var perWeek=parseInt(o.perWeek,10)||2; if(perWeek<1)perWeek=1; if(perWeek>8)perWeek=8;
  var goals=splitLines(o.goals);
  if(!goals.length) goals=['（待补充课程目标）'];
  var mode=String(o.mode||'考试为主').trim()||'考试为主';
  var themes=weekThemes(weeks, goals);
  var assess=assessPlan(mode);
  var totalHours=weeks*perWeek;
  var lines=[];
  lines.push('# 课程大纲：'+name);
  lines.push('');
  lines.push('## 一、基本信息');
  lines.push('- 总周数：'+weeks+' 周');
  lines.push('- 周课时：'+perWeek+' 学时（共 '+totalHours+' 学时）');
  lines.push('- 考核方式：'+mode);
  lines.push('');
  lines.push('## 二、课程目标');
  goals.forEach(function(g,i){ lines.push((i+1)+'. '+g); });
  lines.push('');
  lines.push('## 三、周次安排');
  themes.forEach(function(t,i){ lines.push('- 第 '+(i+1)+' 周：'+t); });
  lines.push('');
  lines.push('## 四、考核构成');
  assess.forEach(function(a){ lines.push('- '+a[0]+'：'+a[1]+'%'); });
  lines.push('');
  lines.push('> 说明：周次主题默认由课程目标轮转填充，请按实际教学进度调整。');
  return {title:name+' 课程大纲', weekCount:themes.length, totalHours:totalHours, markdown:lines.join('\n')};
}
var EXPORTS={splitLines:splitLines, weekThemes:weekThemes, assessPlan:assessPlan, buildSyllabus:buildSyllabus};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.SyllabusForgePure = EXPORTS; }
